SELECT gen_random_uuid()::text, 'formula', '$P_G = \frac{G}{i}\left[(P/A) - n(P/F)\right]$', 'Arithmetic Gradient Present Worth', '$P_G = \frac{G}{i}\left[\frac{1 - (1 + i)^{-n}}{i} - \frac{n}{(1 + i)^n}\right]$', '₱', 'Present worth of a series rising by G each period: 0, G, 2G, …, (n − 1)G.', '[{"symbol":"$G$","meaning":"yearly increase (the first gradient amount is at period 2)","unit":"₱"},{"symbol":"$i$","meaning":"interest rate per period","unit":null},{"symbol":"$n$","meaning":"number of periods","unit":null}]'::jsonb, 'Add the base series separately: P = A₁(P/A) + P_G. For a decreasing series, subtract.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'gradients' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS'
