SELECT gen_random_uuid()::text, 'formula', '$A_G = G\left[\frac{1}{i} - \frac{n}{(1 + i)^n - 1}\right]$', 'Arithmetic Gradient to Annual Worth', '$A_G = G\left[\frac{1}{i} - \frac{n}{(1 + i)^n - 1}\right]$', '₱', 'The uniform series equal to an arithmetic gradient.', '[{"symbol":"$G$","meaning":"yearly increase","unit":"₱"},{"symbol":"$i$","meaning":"interest rate per period","unit":null},{"symbol":"$n$","meaning":"number of periods","unit":null}]'::jsonb, 'A perpetual gradient: P = A/i + G/i².', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'gradients' AND s."active"), NULL, false, 'PENDING', now(), now()
