SELECT gen_random_uuid()::text, 'formula', '$P_g$', 'Geometric Gradient Present Worth', '$P = A_1\left[\frac{1 - \left(\frac{1 + g}{1 + i}\right)^n}{i - g}\right]\ (i \ne g),\qquad P = \frac{nA_1}{1 + i}\ (i = g)$', '₱', 'Present worth of payments that grow by a fixed percentage each period.', '[{"symbol":"$A_1$","meaning":"first payment (end of period 1)","unit":"₱"},{"symbol":"$g$","meaning":"growth rate per period","unit":null},{"symbol":"$i$","meaning":"interest rate per period","unit":null},{"symbol":"$n$","meaning":"number of periods","unit":null}]'::jsonb, 'Escalating fuel or maintenance costs are geometric gradients.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'gradients' AND s."active"), NULL, false, 'PENDING', now(), now()
