SELECT gen_random_uuid()::text, 'formula', '$d = (C_0 - C_L)\frac{i}{(1 + i)^L - 1}$', 'Sinking Fund Depreciation', '$d = (C_0 - C_L)\left[\frac{i}{(1 + i)^L - 1}\right],\qquad BV_n = C_0 - d\left[\frac{(1 + i)^n - 1}{i}\right]$', '₱', 'Depreciation as deposits into a fund that earns interest and reaches C₀ − C_L at the end of the life.', '[{"symbol":"$C_0$","meaning":"first cost","unit":"₱"},{"symbol":"$C_L$","meaning":"salvage value at the end of its life","unit":"₱"},{"symbol":"$L$","meaning":"useful life","unit":"years"},{"symbol":"$i$","meaning":"interest rate per period","unit":null}]'::jsonb, 'Total depreciation after n years is the fund''s value then, not n·d.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'depreciation' AND s."active"), NULL, false, 'PENDING', now(), now()
