SELECT gen_random_uuid()::text, 'formula', '$BV_n = C_0(1 - k)^n$', 'Declining Balance (Matheson)', '$k = 1 - \left(\frac{C_L}{C_0}\right)^{1/L},\qquad d_n = C_0k(1 - k)^{n-1},\qquad BV_n = C_0(1 - k)^n$', '₱', 'Each year writes off the same fraction of what is left.', '[{"symbol":"$C_0$","meaning":"first cost","unit":"₱"},{"symbol":"$C_L$","meaning":"salvage value at the end of its life","unit":"₱"},{"symbol":"$L$","meaning":"useful life","unit":"years"},{"symbol":"$k$","meaning":"fixed yearly rate","unit":null}]'::jsonb, 'It needs a salvage value above zero; heavy early charges suit equipment that ages fast.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'depreciation' AND s."active"), NULL, false, 'PENDING', now(), now()
