SELECT gen_random_uuid()::text, 'formula', '$k = \frac{2}{L}$', 'Double Declining Balance', '$k = \frac{2}{L},\qquad d_n = C_0k(1 - k)^{n-1},\qquad BV_n = C_0(1 - k)^n$', '₱', 'Declining balance at twice the straight-line rate, ignoring salvage.', '[{"symbol":"$C_0$","meaning":"first cost","unit":"₱"},{"symbol":"$L$","meaning":"useful life","unit":"years"}]'::jsonb, 'Book value never goes below the salvage value: stop depreciating once it reaches it.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'depreciation' AND s."active"), NULL, false, 'PENDING', now(), now()
