SELECT gen_random_uuid()::text, 'formula', '$d_n = (C_0 - C_L)\frac{L - n + 1}{SYD}$', 'Sum-of-the-Years''-Digits', '$d_n = (C_0 - C_L)\frac{L - n + 1}{SYD},\qquad SYD = \frac{L(L + 1)}{2}$', '₱', 'Front-loaded depreciation: year 1 takes L/SYD of the total, the last year 1/SYD.', '[{"symbol":"$C_0$","meaning":"first cost","unit":"₱"},{"symbol":"$C_L$","meaning":"salvage value at the end of its life","unit":"₱"},{"symbol":"$L$","meaning":"useful life","unit":"years"},{"symbol":"$n$","meaning":"year","unit":null}]'::jsonb, 'After n years the total is (C₀ − C_L)·n(2L − n + 1)/(L(L + 1)).', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'depreciation' AND s."active"), NULL, false, 'PENDING', now(), now()
