SELECT gen_random_uuid()::text, 'formula', '$d = \frac{C_0 - C_L}{U}\,u$', 'Service Output (Units of Production)', '$d = \frac{C_0 - C_L}{U}\,u$', '₱', 'Depreciation by use rather than by time.', '[{"symbol":"$C_0$","meaning":"first cost","unit":"₱"},{"symbol":"$C_L$","meaning":"salvage value at the end of its life","unit":"₱"},{"symbol":"$U$","meaning":"total units (hours, km, tonnes) in its life","unit":null},{"symbol":"$u$","meaning":"units this year","unit":null}]'::jsonb, 'Depletion of a mine or well works the same way: cost per unit of reserve × units taken.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'depreciation' AND s."active"), NULL, false, 'PENDING', now(), now()
