SELECT gen_random_uuid()::text, 'formula', '$P = Zr(P/A, i, n) + C(P/F, i, n)$', 'Value of a Bond', '$P = Zr\left[\frac{1 - (1 + i)^{-n}}{i}\right] + C(1 + i)^{-n}$', '₱', 'What a bond is worth to a buyer: its coupons and its redemption, discounted at the buyer''s rate.', '[{"symbol":"$Z$","meaning":"face (par) value","unit":"₱"},{"symbol":"$r$","meaning":"bond (coupon) rate per period","unit":null},{"symbol":"$C$","meaning":"redemption value, usually Z","unit":"₱"},{"symbol":"$i$","meaning":"investor''s rate per period","unit":null},{"symbol":"$n$","meaning":"number of periods","unit":null}]'::jsonb, 'If the buyer''s rate equals the coupon rate, the bond sells at par; a higher rate means a discount.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'bonds' AND s."active"), NULL, false, 'PENDING', now(), now()
