SELECT gen_random_uuid()::text, 'formula', '$\text{current yield} = \frac{Zr}{P}$', 'Current Yield of a Bond', '$\text{current yield} = \frac{Zr}{P}$', NULL, 'The interest a bond pays each year as a share of its price.', '[{"symbol":"$Zr$","meaning":"yearly interest paid","unit":"₱"},{"symbol":"$P$","meaning":"market price","unit":"₱"}]'::jsonb, 'It ignores the gain or loss at redemption; the yield to maturity is the i that makes the bond''s value equal its price.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'bonds' AND s."active"), NULL, true, 'PENDING', now(), now()
