SELECT gen_random_uuid()::text, 'formula', '$Q_{BE} = \frac{FC}{p - v}$', 'Break-Even Quantity', '$Q_{BE} = \frac{FC}{p - v},\qquad \text{profit} = (p - v)Q - FC$', 'units', 'The output at which sales just cover all costs.', '[{"symbol":"$FC$","meaning":"fixed cost per period","unit":"₱"},{"symbol":"$p$","meaning":"selling price per unit","unit":"₱"},{"symbol":"$v$","meaning":"variable cost per unit","unit":"₱"}]'::jsonb, 'p − v is the contribution margin: each unit sold covers that much of the fixed cost.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'break-even analysis' AND s."active"), NULL, false, 'PENDING', now(), now()
