SELECT gen_random_uuid()::text, 'formula', '$x = \frac{FC_2 - FC_1}{v_1 - v_2}$', 'Break-Even Between Two Alternatives', '$FC_1 + v_1x = FC_2 + v_2x\ \Rightarrow\ x = \frac{FC_2 - FC_1}{v_1 - v_2}$', NULL, 'The level of use (hours, units) at which two options cost the same.', '[{"symbol":"$FC_1, FC_2$","meaning":"fixed costs (yearly cost of ownership)","unit":"₱"},{"symbol":"$v_1, v_2$","meaning":"costs per unit of use","unit":"₱"},{"symbol":"$x$","meaning":"level of use","unit":null}]'::jsonb, 'Above it, the option with the lower cost per unit wins.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'break-even analysis' AND s."active"), NULL, true, 'PENDING', now(), now()
