SELECT gen_random_uuid()::text, 'formula', '$NPW = \sum_{t=0}^{n}\frac{CF_t}{(1 + i)^t}$', 'Net Present Worth', '$NPW = \sum_{t=0}^{n}\frac{CF_t}{(1 + i)^t}$', '₱', 'All of a project''s cash flows brought to today at the MARR.', '[{"symbol":"$CF_t$","meaning":"net cash flow at the end of period t (outflows negative)","unit":"₱"},{"symbol":"$i$","meaning":"minimum attractive rate of return (MARR)","unit":null}]'::jsonb, 'NPW ≥ 0: the project earns at least the MARR. Compare unequal lives over a common multiple, or use annual worth.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'present and annual worth' AND s."active"), NULL, false, 'PENDING', now(), now()
