SELECT gen_random_uuid()::text, 'formula', '$EUAC = (C_0 - C_L)(A/P, i, n) + C_Li + OM$', 'Equivalent Uniform Annual Cost', '$EUAC = (C_0 - C_L)(A/P, i, n) + C_Li + OM$', '₱', 'An asset''s whole cost as one equal yearly figure: capital recovery plus running costs.', '[{"symbol":"$C_0$","meaning":"first cost","unit":"₱"},{"symbol":"$C_L$","meaning":"salvage value at the end of its life","unit":"₱"},{"symbol":"$OM$","meaning":"yearly operating cost","unit":"₱"},{"symbol":"$i$","meaning":"interest rate per period","unit":null},{"symbol":"$n$","meaning":"number of periods","unit":null}]'::jsonb, 'Equivalently C₀(A/P) − C_L(A/F) + OM. Annual worth compares alternatives with different lives directly.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'present and annual worth' AND s."active"), NULL, false, 'PENDING', now(), now()
