SELECT gen_random_uuid()::text, 'formula', '$n_{pb} = \frac{C_0}{\text{net annual cash flow}}$', 'Payback Period', '$n_{pb} = \frac{C_0}{\text{net annual cash flow}};\qquad \text{discounted: smallest } n \text{ with } \sum_{t=1}^{n} CF_t(1 + i)^{-t} \ge C_0$', 'years', 'How long an investment takes to earn back its cost.', '[{"symbol":"$C_0$","meaning":"first cost","unit":"₱"},{"symbol":"$\\text{net annual cash flow}$","meaning":"yearly savings or income before depreciation","unit":"₱"}]'::jsonb, 'Simple payback ignores interest and everything after it; discounted payback is always longer.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'rate of return and payback' AND s."active"), NULL, false, 'PENDING', now(), now()
