SELECT gen_random_uuid()::text, 'formula', '$F_{\text{in}} = P_{\text{out}}(1 + i'')^n$', 'External (Modified) Rate of Return', '$\sum_t I_t(1 + \varepsilon)^{n - t} = \left[\sum_t O_t(1 + \varepsilon)^{-t}\right](1 + i'')^n$', NULL, 'A single, unambiguous rate: inflows compounded forward and outflows discounted back at an outside rate.', '[{"symbol":"$I_t, O_t$","meaning":"inflows and outflows at period t","unit":"₱"},{"symbol":"$\\varepsilon$","meaning":"external reinvestment rate (often the MARR)","unit":null},{"symbol":"$i''$","meaning":"external rate of return","unit":null}]'::jsonb, 'Use it when cash flows change sign more than once and the IRR is not unique.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'rate of return and payback' AND s."active"), NULL, true, 'PENDING', now(), now()
