SELECT gen_random_uuid()::text, 'formula', '$\frac{B}{C} = \frac{PW_{benefits}}{PW_{costs}}$', 'Benefit-Cost Ratio', '$\frac{B}{C} = \frac{PW(\text{benefits} - \text{disbenefits})}{PW(\text{costs})};\qquad \text{modified: } \frac{B - OM}{C_0}$', NULL, 'The test for public projects: worth doing if B/C ≥ 1.', '[{"symbol":"$B$","meaning":"benefits to the public","unit":"₱"},{"symbol":"$C$","meaning":"costs to the government","unit":"₱"}]'::jsonb, 'The modified ratio moves O&M to the numerator; it can rank differently but gives the same accept/reject.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'benefit-cost ratio' AND s."active"), NULL, true, 'PENDING', now(), now()
