SELECT gen_random_uuid()::text, 'formula', '$\frac{\Delta B}{\Delta C}$', 'Incremental Benefit-Cost Ratio', '$\frac{\Delta B}{\Delta C} = \frac{B_2 - B_1}{C_2 - C_1} \ge 1 \Rightarrow \text{choose the costlier alternative}$', NULL, 'Choosing between public projects: is the extra spending worth it?', '[{"symbol":"$B_1, C_1$","meaning":"benefits and cost of the cheaper option","unit":"₱"},{"symbol":"$B_2, C_2$","meaning":"of the costlier option","unit":"₱"}]'::jsonb, 'Never pick by the highest overall B/C: rank by cost and test each increment.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'benefit-cost ratio' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$EUAC_D \text{ vs } EUAC_C$', 'Defender versus Challenger', '$EUAC_D = (MV - C_L)(A/P, i, n_D) + C_Li + OM_D;\qquad \text{replace if } EUAC_C < EUAC_D$', NULL, 'Keep the old asset (defender) or replace it (challenger): compare their annual costs over their own lives.', '[{"symbol":"$MV$","meaning":"the defender''s market (trade-in) value now","unit":"₱"},{"symbol":"$OM_D$","meaning":"the defender''s yearly cost","unit":"₱"},{"symbol":"$n_D$","meaning":"its remaining life","unit":"years"}]'::jsonb, 'The defender''s cost is its CURRENT market value; its original cost and book value are sunk.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'replacement studies' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$n^* = \arg\min_n EUAC(n)$', 'Economic Service Life', '$EUAC(n) = C_0(A/P, i, n) - MV_n(A/F, i, n) + \left[\sum_{t=1}^{n} OM_t(1 + i)^{-t}\right](A/P, i, n)$', 'years', 'The life that makes an asset''s annual cost lowest: falling capital cost against rising running cost.', '[{"symbol":"$C_0$","meaning":"first cost","unit":"₱"},{"symbol":"$MV_n$","meaning":"market value after n years","unit":"₱"},{"symbol":"$OM_t$","meaning":"operating cost in year t","unit":"₱"},{"symbol":"$i$","meaning":"interest rate per period","unit":null}]'::jsonb, 'Replace at the economic life, not when the asset wears out.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'replacement studies' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$E = \sum p_ix_i$', 'Expected Value', '$E = \sum p_ix_i,\qquad \sum p_i = 1$', '₱', 'The average result of a risky choice, weighting each outcome by its probability (decisions under risk).', '[{"symbol":"$p_i$","meaning":"probability of outcome i","unit":null},{"symbol":"$x_i$","meaning":"payoff of outcome i","unit":"₱"}]'::jsonb, 'The value of perfect information = expected payoff with it − best expected payoff without it.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'decisions under certainty, risk and uncertainty' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$\text{Hurwicz} = \alpha\max + (1 - \alpha)\min$', 'Decision Criteria Under Uncertainty', '$\text{maximax};\ \text{maximin};\ \text{Laplace: } \frac{1}{m}\sum x_j;\ \text{Hurwicz: } \alpha\max_j x_j + (1 - \alpha)\min_j x_j;\ \text{minimax regret}$', '₱', 'Ways to choose when the probabilities are unknown, from optimist to pessimist.', '[{"symbol":"$\\alpha$","meaning":"coefficient of optimism, 0 to 1","unit":null},{"symbol":"$m$","meaning":"number of possible states","unit":null}]'::jsonb, 'Regret = best payoff in that state − this payoff; minimax regret picks the smallest worst regret.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS' AND s."normKey" = 'decisions under certainty, risk and uncertainty' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Engineering Economics' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
